generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName ?score WHERE {
  ?inv wm:investorId ?investorId ;
       wm:investorName ?investorName .

  {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmt)) AS ?cash2025) WHERE {
      ?cf wm:investorId ?investorId ;
          wm:date ?date ;
          wm:amount ?cfAmt .
      FILTER(CONTAINS(LCASE(STR(?date)), "2025"))
    } GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?rebAmt)) AS ?rebalanceAmt) WHERE {
      ?ra wm:investorId ?investorId ;
          wm:amount ?rebAmt .
    } GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?sf)) AS ?shortfallSum) WHERE {
      ?goal wm:investorId ?investorId ;
            wm:shortfall ?sf .
    } GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?new) - xsd:decimal(?cur)) AS ?allocChange) WHERE {
      ?sc wm:investorId ?investorId ;
          wm:newAllocationPct ?new ;
          wm:currentAllocationPct ?cur .
    } GROUP BY ?investorId
  }

  BIND ( (xsd:decimal(?cash2025) + xsd:decimal(?rebalanceAmt) - xsd:decimal(?shortfallSum) + xsd:decimal(?allocChange)) AS ?score )
}
ORDER BY DESC(?score)
LIMIT 10

