PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName ?score WHERE {
  ?inv wm:investorName ?investorName .

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?amt)) AS ?cash2025) WHERE {
      ?inv wm:hasCashFlow ?cf .
      ?cf wm:date ?date ;
          wm:amount ?amt .
      FILTER(CONTAINS(LCASE(STR(?date)), "2025"))
    } GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?rebAmt)) AS ?rebalanceAmt) WHERE {
      ?inv wm:hasRebalancingAction ?ra .
      ?ra wm:amount ?rebAmt .
    } GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?sf)) AS ?shortfallSum) WHERE {
      ?inv wm:hasInvestmentGoal ?goal .
      ?goal wm:shortfall ?sf .
    } GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?new) - xsd:decimal(?cur)) AS ?allocChange) WHERE {
      ?inv wm:hasScenarioRebalancing ?sc .
      ?sc wm:newAllocationPct ?new ;
          wm:currentAllocationPct ?cur .
    } GROUP BY ?inv
  }

  BIND( (COALESCE(?cash2025, 0) + COALESCE(?rebalanceAmt, 0) - COALESCE(?shortfallSum, 0) + COALESCE(?allocChange, 0)) AS ?score )
}
ORDER BY DESC(?score)
LIMIT 10

